-- EVT hook file for ability_list_menu (VRFW_Host handlers, docs/framework/lua-hosts.md). Graft character_reforged_board (table_picker_create_hooks.lua). Generated by research/scripts/menu_assemble.py; do not edit by hand.
-- Character Reforged › the «Fantasy» skill table's move picker (ability_list_menu in pick mode, graft ss2_menus) when
-- a «Crear …» row is picked (graft character_reforged_board; owner 2026-10-14: «debería ser darle y pasar directamente
-- al banco»). HOOK file (graft [[hooks]], shipped as is): it wraps the picker's globals OnInit and Step and calls them;
-- no retail or Character Reforged function is replaced.
--   * OnInit: the shown player (param evt_ss_mx_base, written by the skill table before its aura / mix picker opens);
--   * Step: the frame the picker commits a «create» item (its result param evt_ss_pick_result), the partner bank opens
--     while the picker closes, the skill table hidden under it (CharacterReforged.CreateCard.OpenBankEarly); the
--     table's create flow (table_create_entry_hooks.lua) then only waits for that bank.
-- Inazuma Fantasy keeps its own flow (its commands answer CMND_EVT_MX_ITEMS): nothing here then. Definitions and wraps
-- only at chunk load (no engine call).
do
  CharacterReforged_PickerCreate = CharacterReforged_PickerCreate or {}
  local Picker = CharacterReforged_PickerCreate
  Picker.KEY_BASE = 19616700                         -- evt_ss_mx_base: the shown player (skill table)
  Picker.KEY_RESULT = 3854106930                     -- evt_ss_pick_result: the picked item
  Picker.PARAM_HAS = 2947612279
  Picker.PARAM_GET = 3522198769
  Picker.INAZUMA_FANTASY_ITEMS = 464382964           -- CMND_EVT_MX_ITEMS: answered only by Inazuma Fantasy
  Picker.SKILL_TABLE = 1041963128                    -- evt_skill_slot_menu (hidden under the bank)
  Picker.base, Picker.done = 0, true

  function Picker.Card()
    local cr = rawget(_G, "CharacterReforged")
    return type(cr) == "table" and type(cr.CreateCard) == "table" and cr.CreateCard or nil
  end

  function Picker.WrapGlobal(name, make)
    Picker.wrappers = Picker.wrappers or {}
    local current = _ENV[name]
    if current == nil or Picker.wrappers[name] == current then
      return
    end
    local wrapper = make(current)
    Picker.wrappers[name] = wrapper
    _ENV[name] = wrapper
  end

  Picker.WrapGlobal("OnInit", function(previous)
    return function(...)
      Picker.base, Picker.done = 0, true
      pcall(function()
        local ok, answer = pcall(funcLuaCommand, Picker.INAZUMA_FANTASY_ITEMS)
        if ok and type(answer) == "number" then
          return                                     -- Inazuma Fantasy's own flow
        end
        if funcLuaCommand(Picker.PARAM_HAS, Picker.KEY_BASE) == true then
          local h = funcLuaCommand(Picker.PARAM_GET, Picker.KEY_BASE)
          Picker.base = type(h) == "number" and h or 0
          Picker.done = Picker.base == 0
        end
      end)
      return previous(...)
    end
  end)

  Picker.WrapGlobal("Step", function(previous)
    return function(...)
      local r = table.pack(previous(...))
      if not Picker.done then
        pcall(function()
          if funcLuaCommand(Picker.PARAM_HAS, Picker.KEY_RESULT) ~= true then
            return
          end
          local card = Picker.Card()
          local item = card ~= nil and card.U32(funcLuaCommand(Picker.PARAM_GET, Picker.KEY_RESULT)) or 0
          Picker.done = true                         -- one commit per picker
          if card ~= nil and card.IsCreate(item) then
            card.OpenBankEarly(Picker.base, item, Picker.SKILL_TABLE)
          end
        end)
      end
      return table.unpack(r, 1, r.n)
    end
  end)
end
